bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import {readPrivateToken} from '/opt/videobot/src/runtime/config.mjs';
import {createTelegramBotApi} from '/opt/videobot/src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
const env=process.env;
const outbound=createCreatorTelegramFetch();
try{
 const api=createTelegramBotApi({token:readPrivateToken(env.VIDEOBOT_TELEGRAM_TOKEN_FILE),fetchImpl:outbound.fetch,timeoutMs:25000,baseUrl:env.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org'});
 const target=-1002373696859;
 const master=788044853;
 const [chat,member]=await Promise.all([api('getChat',{chat_id:target}),api('getChatMember',{chat_id:target,user_id:master})]);
 console.log('BOARD_TYPE='+String(chat?.type??'unknown'));
 console.log('BOARD_IS_FORUM='+Boolean(chat?.is_forum));
 console.log('MASTER_ID_MEMBERSHIP='+String(member?.status??'unknown'));
 console.log('MASTER_CAN_POST='+Boolean(member?.can_post_messages||member?.can_manage_topics||member?.status==='creator'));
 console.log('NO_ACCOUNT_SESSION_DATA_ACCESSED=YES');
}finally{await outbound.close()}
JS
